import Foundation
import Testing
@testable import Aidoku

@Suite struct LargeDownloadConfirmationTests {
    private let key = AppSettings.downloads.confirmLargeDownloads.key

    /// Runs a body against a dedicated defaults suite that is removed afterwards.
    private func withDefaults(_ body: (UserDefaults, String) throws -> Void) rethrows {
        let suite = "LargeDownloadConfirmationTests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        try body(defaults, suite)
    }

    @Test func exactlyThresholdWithSettingOnNeedsNoConfirmation() {
        withDefaults { defaults, _ in
            defaults.set(true, forKey: key)
            #expect(LargeDownloadConfirmation.needsConfirmation(chapterCount: 50, defaults: defaults) == false)
        }
    }

    @Test func aboveThresholdWithSettingOnNeedsConfirmation() {
        withDefaults { defaults, _ in
            defaults.set(true, forKey: key)
            #expect(LargeDownloadConfirmation.needsConfirmation(chapterCount: 51, defaults: defaults))
        }
    }

    @Test func aboveThresholdWithSettingOffNeedsNoConfirmation() {
        withDefaults { defaults, _ in
            defaults.set(false, forKey: key)
            #expect(LargeDownloadConfirmation.needsConfirmation(chapterCount: 51, defaults: defaults) == false)
        }
    }

    @Test func aboveThresholdWithSettingNeverStoredNeedsNoConfirmation() {
        withDefaults { defaults, _ in
            #expect(LargeDownloadConfirmation.needsConfirmation(chapterCount: 51, defaults: defaults) == false)
        }
    }
}
EOF
